const money=(n:any)=>n==null?'Qiymət soruşun':`${Number(n).toLocaleString('az-AZ')} AZN`;
const priceOf=(item:Listing)=>item.daily_price ?? item.price;
const titleOf=(item:Listing)=>item.brand||item.model?`${item.brand||''} ${item.model||''}`.trim():item.title||item.dealer_name||item.name||item.details?.company_name||item.specialty||'A-USTA elanı';
