 if(loading)return <State loading title="Elan açılır" body="Elan və icazəli media yoxlanılır…"/>;if(error||!item)return <State title="Elanı açmaq mümkün olmadı" body={error||'Elan tapılmadı.'} action="Geri qayıt" onAction={()=>router.back()}/>;
